sql.where:
t.deleted = 0

    AND t.txn_no LIKE CONCAT('%', #{req.txnNo}, '%')


    AND t.prod_order_id = #{req.prodOrderId}


    AND t.work_order_id = #{req.workOrderId}


    AND t.op_task_id = #{req.opTaskId}


    AND t.txn_type = #{req.txnType}


    AND t.biz_type = #{req.bizType}


    AND t.biz_no LIKE CONCAT('%', #{req.bizNo}, '%')


    AND t.txn_time BETWEEN #{req.txnTime[0]} AND #{req.txnTime[1]}


    AND t.create_time BETWEEN #{req.createTime[0]} AND #{req.createTime[1]}
